<script>
import { GlButton, GlTooltipDirective, GlLoadingIcon } from '@gitlab/ui';
import { EditorContent as TiptapEditorContent } from '@tiptap/vue-2';
import { isEqual } from 'lodash-es';
import { markRaw } from 'vue';
import { __ } from '~/locale';
import { VARIANT_DANGER } from '~/alert';
import EditorModeSwitcher from '~/vue_shared/components/markdown/editor_mode_switcher.vue';
import { CONTENT_EDITOR_READY_EVENT, CONTENT_EDITOR_PASTE } from '~/vue_shared/constants';
import markdownEditorEventHub from '~/vue_shared/components/markdown/eventhub';
import SidebarMediator from '~/sidebar/sidebar_mediator';
import { createContentEditor } from '../services/create_content_editor';
import { ALERT_EVENT, TIPTAP_AUTOFOCUS_OPTIONS } from '../constants';
import ContentEditorAlert from './content_editor_alert.vue';
import ContentEditorProvider from './content_editor_provider.vue';
import EditorStateObserver from './editor_state_observer.vue';
import AlertBubbleMenu from './bubble_menus/alert_bubble_menu.vue';
import CodeBlockBubbleMenu from './bubble_menus/code_block_bubble_menu.vue';
import LinkBubbleMenu from './bubble_menus/link_bubble_menu.vue';
import MediaBubbleMenu from './bubble_menus/media_bubble_menu.vue';
import ReferenceBubbleMenu from './bubble_menus/reference_bubble_menu.vue';
import TableBubbleMenu from './bubble_menus/table_bubble_menu.vue';
import FormattingToolbar from './formatting_toolbar.vue';

export default {
  name: 'ContentEditor',
  components: {
    GlButton,
    GlLoadingIcon,
    ContentEditorAlert,
    ContentEditorProvider,
    TiptapEditorContent,
    FormattingToolbar,
    AlertBubbleMenu,
    CodeBlockBubbleMenu,
    LinkBubbleMenu,
    MediaBubbleMenu,
    EditorStateObserver,
    ReferenceBubbleMenu,
    TableBubbleMenu,
    EditorModeSwitcher,
  },
  directives: {
    GlTooltip: GlTooltipDirective,
  },
  props: {
    renderMarkdown: {
      type: Function,
      required: true,
    },
    markdownDocsPath: {
      type: String,
      required: true,
    },
    uploadsPath: {
      type: String,
      required: true,
    },
    extensions: {
      type: Array,
      required: false,
      default: () => [],
    },
    serializerConfig: {
      type: Object,
      required: false,
      default: () => {},
    },
    markdown: {
      type: String,
      required: false,
      default: '',
    },
    placeholder: {
      type: String,
      required: false,
      default: '',
    },
    autofocus: {
      type: [String, Boolean],
      required: false,
      default: false,
      validator: (autofocus) => TIPTAP_AUTOFOCUS_OPTIONS.includes(autofocus),
    },
    supportsQuickActions: {
      type: Boolean,
      required: false,
      default: false,
    },
    supportsTableOfContents: {
      type: Boolean,
      required: false,
      default: false,
    },
    drawioEnabled: {
      type: Boolean,
      required: false,
      default: false,
    },
    codeSuggestionsConfig: {
      type: Object,
      required: false,
      default: () => ({}),
    },
    editable: {
      type: Boolean,
      required: false,
      default: true,
    },
    enableAutocomplete: {
      type: Boolean,
      required: false,
      default: true,
    },
    autocompleteDataSources: {
      type: Object,
      required: false,
      default: () => ({}),
    },
    disableAttachments: {
      type: Boolean,
      required: false,
      default: false,
    },
    newCommentTemplatePaths: {
      type: Array,
      required: false,
      default: () => [],
    },
    immersive: {
      type: Boolean,
      required: false,
      default: false,
    },
  },
  data() {
    return {
      focused: false,
      isLoading: false,
      latestMarkdown: null,
    };
  },
  computed: {
    showPlaceholder() {
      return this.placeholder && !this.markdown && !this.focused;
    },
  },
  watch: {
    autocompleteDataSources(newDataSources, oldDataSources) {
      if (!isEqual(newDataSources, oldDataSources)) {
        this.contentEditor.updateAutocompleteDataSources(newDataSources);
      }
    },
    markdown(markdown) {
      if (markdown !== this.latestMarkdown) {
        this.setSerializedContent(markdown);
      }
    },
    editable(value) {
      this.contentEditor.setEditable(value);
    },
  },
  created() {
    const {
      renderMarkdown,
      uploadsPath,
      extensions,
      serializerConfig,
      autofocus,
      drawioEnabled,
      supportsTableOfContents,
      editable,
      enableAutocomplete,
      autocompleteDataSources,
      codeSuggestionsConfig,
    } = this;

    // This is a non-reactive attribute intentionally since this is a complex object.
    this.contentEditor = markRaw(
      createContentEditor({
        renderMarkdown,
        uploadsPath,
        extensions,
        serializerConfig,
        drawioEnabled,
        supportsTableOfContents,
        enableAutocomplete,
        autocompleteDataSources,
        codeSuggestionsConfig,
        sidebarMediator: SidebarMediator.singleton,
        tiptapOptions: {
          autofocus,
          editable,
          editorProps: {
            attributes: {
              'aria-controls': 'content-editor-suggestions',
              'aria-label': __('Rich text editor'),
              class: 'rte-text-box',
            },
          },
        },
      }),
    );
  },
  async mounted() {
    this.$emit('initialized');
    await this.setSerializedContent(this.markdown);
    markdownEditorEventHub.$emit(CONTENT_EDITOR_READY_EVENT);
    markdownEditorEventHub.$on(CONTENT_EDITOR_PASTE, this.pasteContent);

    // Set editor height if stored
    this.contentEditor.tiptapEditor.view.dom.style.minHeight = this.getEditorSelectorDataset();

    // Add event listener for custom resize event
    document.addEventListener('mousedown', this.handleManualResize);
  },
  beforeDestroy() {
    markdownEditorEventHub.$off(CONTENT_EDITOR_PASTE, this.pasteContent);
    this.contentEditor.dispose();
  },
  methods: {
    editorSelector() {
      return this.contentEditor?.tiptapEditor?.view?.dom?.closest('.js-editor');
    },
    setEditorSelectorDataset(value) {
      this.editorSelector().dataset.gfmEditorMinHeight = value;
    },
    getEditorSelectorDataset() {
      return this.editorSelector()?.dataset?.gfmEditorMinHeight;
    },
    handleManualResize(e) {
      const textarea = this.contentEditor.tiptapEditor.view.dom;
      const rect = textarea.getBoundingClientRect();
      const mouseX = e.clientX;
      const mouseY = e.clientY;
      const cornerSize = 16;
      const isInBottomRight =
        mouseX >= rect.right - cornerSize &&
        mouseX <= rect.right &&
        mouseY >= rect.bottom - cornerSize &&
        mouseY <= rect.bottom;

      if (isInBottomRight) {
        this.isManuallyResizing = true;
        textarea.style.minHeight = null;
        this.setEditorSelectorDataset(null);

        document.addEventListener('mouseup', this.handleManualResizeUp);
      }
    },
    handleManualResizeUp() {
      const textarea = this.contentEditor.tiptapEditor.view.dom;

      // Set current height as min height, so autogrow will still work
      if (textarea) {
        const editorHeight = `${textarea.offsetHeight}px`;
        textarea.style.minHeight = editorHeight;
        // Store minHeight in global variable for RTE
        this.setEditorSelectorDataset(editorHeight);
      }

      document.removeEventListener('mouseup', this.handleManualResizeUp);
    },
    pasteContent(content) {
      this.contentEditor.tiptapEditor.chain().focus().pasteContent(content).run();
    },
    async setSerializedContent(markdown) {
      this.notifyLoading();

      try {
        await this.contentEditor.setSerializedContent(markdown);
        this.notifyLoadingSuccess();
        this.latestMarkdown = markdown;
      } catch {
        this.contentEditor.setEditable(false);
        this.contentEditor.eventHub.$emit(ALERT_EVENT, {
          message: __(
            'An error occurred while trying to render the rich text editor. Please try again.',
          ),
          variant: VARIANT_DANGER,
          actionLabel: __('Retry'),
          action: () => {
            this.contentEditor.setEditable(true);
            this.setSerializedContent(markdown);
          },
        });
        this.notifyLoadingError();
      }
    },
    // eslint-disable-next-line vue/no-unused-properties -- focus() is part of the component's public API.
    focus() {
      this.contentEditor.tiptapEditor.commands.focus();
    },
    onFocus() {
      this.focused = true;
      this.$emit('focus');
    },
    onBlur() {
      this.focused = false;
      this.$emit('blur');
    },
    notifyLoading() {
      this.isLoading = true;
      this.$emit('loading');
    },
    notifyLoadingSuccess() {
      this.isLoading = false;
      this.$emit('loadingSuccess');
    },
    notifyLoadingError(error) {
      this.isLoading = false;
      this.$emit('loadingError', error);
    },
    notifyChange() {
      this.latestMarkdown = this.contentEditor.getSerializedContent();

      this.$emit('change', {
        markdown: this.latestMarkdown,
      });
    },
    handleEditorModeChanged() {
      this.$emit('enableMarkdownEditor');
    },
  },
};
</script>
<template>
  <content-editor-provider :content-editor="contentEditor">
    <div
      class="md-area"
      data-testid="content-editor-container"
      :class="{ 'immersive !gl-border-none !gl-bg-inherit': immersive, 'gl-relative': !immersive }"
    >
      <gl-loading-icon
        v-if="isLoading"
        size="lg"
        :class="{ 'gl-bg-alpha-light-36 dark:gl-bg-alpha-dark-40': !immersive }"
        class="gl-absolute gl-bottom-0 gl-top-0 gl-z-1 gl-flex gl-w-full gl-items-center gl-justify-center"
      />
      <editor-state-observer
        @docUpdate="notifyChange"
        @focus="onFocus"
        @blur="onBlur"
        @keydown="$emit('keydown', $event)"
      />
      <content-editor-alert />
      <div data-testid="content-editor" :class="{ 'is-focused': focused }" class="gl-relative">
        <div
          data-testid="content-editor-header"
          :class="{
            'gl-sticky gl-top-0 gl-z-3 gl-bg-default': immersive,
          }"
        >
          <slot name="header"></slot>
          <formatting-toolbar
            ref="toolbar"
            :supports-quick-actions="supportsQuickActions"
            :hide-attachment-button="disableAttachments"
            :new-comment-template-paths-prop="newCommentTemplatePaths"
            :class="{ 'gl-pt-0': immersive }"
            @enableMarkdownEditor="$emit('enableMarkdownEditor')"
          >
            <template #header-buttons>
              <slot name="header-buttons"></slot>
              <editor-mode-switcher
                v-if="immersive"
                size="small"
                value="richText"
                @switch="handleEditorModeChanged"
              />
            </template>
          </formatting-toolbar>
        </div>
        <div v-if="showPlaceholder" class="gl-absolute gl-w-full">
          <div class="placeholder gl-pt-4 gl-text-disabled" :class="{ 'gl-px-5': !immersive }">
            {{ placeholder }}
          </div>
        </div>
        <tiptap-editor-content
          class="md !gl-static"
          data-testid="content_editor_editablebox"
          :editor="contentEditor.tiptapEditor"
        />

        <alert-bubble-menu />
        <code-block-bubble-menu />
        <link-bubble-menu />
        <media-bubble-menu />
        <reference-bubble-menu />
        <table-bubble-menu />
      </div>
      <div
        v-if="!immersive"
        data-testid="content-editor-footer"
        class="gl-border-t gl-flex gl-flex-row gl-items-center gl-justify-between gl-rounded-bl-base gl-rounded-br-base gl-border-default gl-px-2"
      >
        <editor-mode-switcher size="small" value="richText" @switch="handleEditorModeChanged" />
        <slot name="toolbar"></slot>
        <gl-button
          v-gl-tooltip
          icon="markdown-mark"
          :href="markdownDocsPath"
          target="_blank"
          category="tertiary"
          size="small"
          :title="__('Markdown is supported')"
          :aria-label="__('Markdown is supported')"
          class="!gl-px-3"
        />
      </div>
    </div>
  </content-editor-provider>
</template>
